CREATE TABLE public.company_positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),scope_id uuid REFERENCES public.organization_scopes(id),name text NOT NULL,area text NOT NULL DEFAULT '',required_skills text[] NOT NULL DEFAULT '{}',course_ids uuid[] NOT NULL DEFAULT '{}');
GRANT SELECT ON public.company_positions TO authenticated; GRANT ALL ON public.company_positions TO service_role; ALTER TABLE public.company_positions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),user_id uuid NOT NULL,full_name text NOT NULL,email text NOT NULL,scope_id uuid REFERENCES public.organization_scopes(id),current_position_id uuid REFERENCES public.company_positions(id),target_position_id uuid REFERENCES public.company_positions(id),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,UNIQUE(company_id,user_id));
GRANT SELECT ON public.company_employees TO authenticated; GRANT ALL ON public.company_employees TO service_role; ALTER TABLE public.company_employees ENABLE ROW LEVEL SECURITY;
INSERT INTO public.company_employees(company_id,user_id,full_name,email) SELECT company_id,id,full_name,COALESCE(email,'') FROM public.profiles WHERE role='colaborador' AND company_id IS NOT NULL;
CREATE POLICY positions_read ON public.company_positions FOR SELECT TO authenticated USING(public.organization_permission(company_id,'empresa','cargos',scope_id) OR EXISTS(SELECT 1 FROM public.company_employees e WHERE e.user_id=auth.uid() AND e.ended_at IS NULL AND e.company_id=company_positions.company_id AND public.current_profile_role()='colaborador'));
CREATE POLICY employees_read ON public.company_employees FOR SELECT TO authenticated USING((user_id=auth.uid() AND public.current_profile_role()='colaborador' AND ended_at IS NULL) OR public.organization_permission(company_id,'empresa','colaboradores',scope_id) OR public.organization_permission(company_id,'empresa','competencias',scope_id));
CREATE OR REPLACE FUNCTION public.manage_company(_company uuid,_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scope uuid; target uuid; existing public.company_employees; position public.company_positions; result uuid; ids uuid[]; skills text[]; BEGIN scope:=NULLIF(_payload->>'scope_id','')::uuid; IF _action='position' THEN IF NOT public.organization_permission(_company,'empresa','cargos',scope) THEN RAISE EXCEPTION 'Permissão de cargos necessária'; END IF; IF length(trim(COALESCE(_payload->>'name','')))<2 THEN RAISE EXCEPTION 'Informe o cargo'; END IF; SELECT COALESCE(array_agg(value),'{}') INTO skills FROM jsonb_array_elements_text(COALESCE(_payload->'required_skills','[]')); SELECT COALESCE(array_agg(value::uuid),'{}') INTO ids FROM jsonb_array_elements_text(COALESCE(_payload->'course_ids','[]')); IF _payload->>'id' IS NOT NULL THEN SELECT * INTO position FROM public.company_positions WHERE id=(_payload->>'id')::uuid AND company_id=_company; IF NOT FOUND OR NOT public.organization_permission(_company,'empresa','cargos',position.scope_id) THEN RAISE EXCEPTION 'Cargo fora do escopo'; END IF; UPDATE public.company_positions SET name=_payload->>'name',area=COALESCE(_payload->>'area',''),required_skills=skills,course_ids=ids,scope_id=scope WHERE id=position.id RETURNING id INTO result; ELSE INSERT INTO public.company_positions(company_id,scope_id,name,area,required_skills,course_ids) VALUES(_company,scope,_payload->>'name',COALESCE(_payload->>'area',''),skills,ids) RETURNING id INTO result; END IF;
ELSIF _action IN ('employee','offboard') THEN IF _action='offboard' THEN SELECT * INTO existing FROM public.company_employees WHERE id=(_payload->>'id')::uuid AND company_id=_company FOR UPDATE; target:=existing.user_id; scope:=existing.scope_id; ELSE SELECT id INTO target FROM public.profiles WHERE lower(email)=lower(trim(_payload->>'email')); IF target IS NULL THEN RAISE EXCEPTION 'Colaborador deve criar sua conta antes do vínculo'; END IF; SELECT * INTO existing FROM public.company_employees WHERE company_id=_company AND user_id=target; IF existing.id IS NOT NULL AND NOT public.organization_permission(_company,'empresa','colaboradores',existing.scope_id) THEN RAISE EXCEPTION 'Colaborador fora do escopo'; END IF; END IF; IF target IS NULL OR NOT public.organization_permission(_company,'empresa','colaboradores',scope) THEN RAISE EXCEPTION 'Gestão de colaboradores não autorizada'; END IF;
IF _action='offboard' THEN UPDATE public.company_employees SET ended_at=now() WHERE id=existing.id; IF NOT EXISTS(SELECT 1 FROM public.test_profile_access WHERE user_id=target) THEN INSERT INTO public.learner_profiles(user_id,profile_role,education_level,works,seeks_job,target_area,target_position,xp,level) SELECT user_id,'geral',education_level,works,seeks_job,target_area,target_position,xp,level FROM public.learner_profiles WHERE user_id=target AND profile_role='colaborador' ON CONFLICT DO NOTHING; INSERT INTO public.enrollments(user_id,course_id,progress,completed_at,profile_role) SELECT user_id,course_id,progress,completed_at,'geral' FROM public.enrollments WHERE user_id=target AND profile_role='colaborador' ON CONFLICT(user_id,course_id,profile_role) DO UPDATE SET progress=greatest(enrollments.progress,EXCLUDED.progress); INSERT INTO public.certificates(user_id,course_id,code,hours,issued_at,profile_role,module_id,assessment_id,complementary,legacy) SELECT user_id,course_id,code,hours,issued_at,'geral',module_id,assessment_id,complementary,legacy FROM public.certificates WHERE user_id=target AND profile_role='colaborador' ON CONFLICT DO NOTHING; UPDATE public.profiles SET role='geral',company_id=NULL,matching_enabled=false WHERE id=target AND company_id=_company; ELSE UPDATE public.test_profile_access SET company_id=NULL WHERE user_id=target AND role='colaborador'; END IF; UPDATE public.organization_memberships SET status='removido' WHERE organization_id=_company AND user_id=target; result:=existing.id;
ELSE IF EXISTS(SELECT 1 FROM public.profiles WHERE id=target AND role IN ('professor','ies','empresa')) THEN RAISE EXCEPTION 'Conta já possui perfil organizacional ou de autor'; END IF; IF EXISTS(SELECT 1 FROM public.company_employees WHERE user_id=target AND company_id<>_company AND ended_at IS NULL) THEN RAISE EXCEPTION 'Conta já vinculada a outra empresa'; END IF; IF EXISTS(SELECT 1 FROM public.company_positions WHERE id IN (NULLIF(_payload->>'current_position_id','')::uuid,NULLIF(_payload->>'target_position_id','')::uuid) AND (company_id<>_company OR (scope_id IS NOT NULL AND scope_id IS DISTINCT FROM scope))) THEN RAISE EXCEPTION 'Cargo de outro escopo'; END IF; INSERT INTO public.company_employees(company_id,user_id,full_name,email,scope_id,current_position_id,target_position_id) SELECT _company,id,full_name,COALESCE(email,''),scope,NULLIF(_payload->>'current_position_id','')::uuid,NULLIF(_payload->>'target_position_id','')::uuid FROM public.profiles WHERE id=target ON CONFLICT(company_id,user_id) DO UPDATE SET scope_id=EXCLUDED.scope_id,current_position_id=EXCLUDED.current_position_id,target_position_id=EXCLUDED.target_position_id,ended_at=NULL RETURNING id INTO result; UPDATE public.profiles SET role='colaborador',company_id=_company,matching_enabled=false WHERE id=target; INSERT INTO public.learner_profiles(user_id,profile_role) VALUES(target,'colaborador') ON CONFLICT DO NOTHING; END IF;
ELSE RAISE EXCEPTION 'Ação inválida'; END IF; IF scope IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.organization_scopes WHERE id=scope AND organization_id=_company AND organization_type='empresa') THEN RAISE EXCEPTION 'Escopo de outra organização'; END IF; INSERT INTO public.activity_logs(user_id,organization_id,organization_type,scope_id,action,entity,meta) VALUES(auth.uid(),_company,'empresa',scope,'empresa_'||_action,'company_employees',jsonb_build_object('target_id',result)); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.manage_company(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_company(uuid,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.employee_competencies(_company uuid) RETURNS TABLE(employee_id uuid,skill text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT e.id,s.name FROM public.company_employees e JOIN public.certificates ce ON ce.user_id=e.user_id AND ce.profile_role='colaborador' JOIN public.course_skills cs ON cs.course_id=ce.course_id JOIN public.skills s ON s.id=cs.skill_id WHERE e.company_id=_company AND e.ended_at IS NULL AND public.organization_permission(e.company_id,'empresa','competencias',e.scope_id) $$;
REVOKE ALL ON FUNCTION public.employee_competencies(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.employee_competencies(uuid) TO authenticated;